import os,glob,re,json,numpy as np
def load():
    d=os.path.normpath(os.environ['RLM_SESSION_DIR'])
    t=open(d+'/../../sessions/'+os.path.basename(d)+'.jsonl').read().replace('\\n','\n'); G={}
    for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n',t):
        k,h,w=m[1],int(m[2]),int(m[3])
        rows=[r.split() for r in t[m.end():].split('\n')[:h]]
        if k not in G and all(len(r)==w and all(x.isdigit() for x in r) for r in rows):
            G[k]=[[int(x) for x in r] for r in rows]
    return G
G=load()

def transform(grid):
    g=[row[:] for row in grid]; H=len(g); W=len(g[0])
    out=[[0]*W for _ in range(H)]
    # collect objects by color (each color = one object here)
    cells={}
    for r in range(H):
        for c in range(W):
            if g[r][c]: cells.setdefault(g[r][c],[]).append((r,c))
    anchor=None
    for col,pts in cells.items():
        rs=[p[0] for p in pts]
        if col==8: anchor=(min(rs),pts)
    tr=anchor[0]
    for col,pts in cells.items():
        rs=[p[0] for p in pts]; dr=tr-min(rs)
        for r,c in pts: out[r+dr][c]=col
    return out

ok=True
for k in ['Demo pair 1','Demo pair 2']:
    pred=transform(G[k+' input']); exp=G[k+' output']
    m=pred==exp; ok&=m; print(k,m)
    if not m:
        print(np.array(pred)); print(np.array(exp))
print('all ok',ok)
out=transform(G['Test input'])
print(json.dumps(out))
